import{_ as t,o,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年9月2日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-09-02.md","filePath":"science-log/src/reconstructed/2026-09-02.md"}'),e={name:"science-log/src/reconstructed/2026-09-02.md"};function a(g,r,i,l,c,p){return o(),n("div",null,[...r[0]||(r[0]=[s('<h1 id="🔬-科学快报-2026年9月2日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年9月2日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年9月2日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年9月2日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-09-02 为<strong>周三</strong>（工作日，期刊正常刊出），但 ScienceDaily 仓库当日<strong>无简讯文件</strong>，故按发布日期回溯重建。CrossRef 当日命中：Nature（0028-0836）39 条，其中 <strong><code>10.1038/s41586-…</code> 研究论文 21 条</strong>（其余为 <code>d41586</code> 新闻 / Author Correction / Retraction Note，已剔除）；Science 系（10.1126）11 条，多为 Science Translational Medicine 与新闻稿，研究论文偏少；PNAS（0027-8424）17 条。科学 5 篇取 Nature ×4 + PNAS ×1；AI 5 篇取自当日 arXiv cs.AI 提交（submittedDate <code>[202609020000 TO 202609022359]</code> 命中达 max_results 上限 30 篇）。期号因当日原本无刊期，标为 <code>（第 ? 期 · 事后重建版）</code>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202609020000 TO 202609022359]</code>（cs.AI）｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🐭-晚年才开始用司美格鲁肽-仍能减缓雌鼠衰老并延长寿命" tabindex="-1">🐭 晚年才开始用司美格鲁肽，仍能减缓雌鼠衰老并延长寿命 <a class="header-anchor" href="#🐭-晚年才开始用司美格鲁肽-仍能减缓雌鼠衰老并延长寿命" aria-label="Permalink to &quot;🐭 晚年才开始用司美格鲁肽，仍能减缓雌鼠衰老并延长寿命&quot;">​</a></h3><p><strong>Late-life semaglutide treatment slows ageing and extends lifespan in female mice</strong><em>Nature（2026-09-02）</em></p><p>GLP-1 受体激动剂长期被视作降糖减重药物，但其「多效性」背后的机制一直不清。Yufan Feng 等（11 位作者）给 <strong>20 月龄</strong>（相当于人类中老年）的雌性 C57BL/6 小鼠连续 <strong>3 个月</strong>给药<strong>司美格鲁肽</strong>，发现小鼠生理功能改善、衰老标志物（hallmarks of ageing）减轻，营养感应通路与保守的衰老遗传调控因子被重新调制。<strong>继续给药可延长寿命</strong>，且这些效应与<strong>热量限制</strong>（caloric restriction）这一经典延寿干预的关键特征高度平行。这提示 GLP-1 类药物可能不止作用于代谢，而是触及了衰老的核心调控网络。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10940-7" target="_blank" rel="noreferrer">10.1038/s41586-026-10940-7</a></p><h3 id="🦠-猴痘病毒「复制体」首次被解析-聚合酶与解旋酶—引物酶如何组装" tabindex="-1">🦠 猴痘病毒「复制体」首次被解析：聚合酶与解旋酶—引物酶如何组装 <a class="header-anchor" href="#🦠-猴痘病毒「复制体」首次被解析-聚合酶与解旋酶—引物酶如何组装" aria-label="Permalink to &quot;🦠 猴痘病毒「复制体」首次被解析：聚合酶与解旋酶—引物酶如何组装&quot;">​</a></h3><p><strong>Structure and operating principles of a monkeypox virus replisome</strong><em>Nature（2026-09-02）</em></p><p>猴痘病毒（MPXV）已两次被 WHO 宣布为国际关注的突发公共卫生事件，但其基因组复制机器如何组装一直不明。痘病毒聚合酶由三个亚基组成——催化亚基 <strong>F8</strong> 与异二聚体持续因子 <strong>A22/E4</strong>；复制起始还必须与六聚体<strong>解旋酶—引物酶 E5</strong> 协同。此前 E5 与聚合酶<strong>各自</strong>的结构虽已解析，但二者<strong>如何在功能上装配成复制体</strong>仍是空白；且分离态 E5 处于<strong>自抑制构象</strong>。Zishuo Yu 等（9 位作者）解析了装配态复制体的结构，给出其<strong>运作原理</strong>，为抗痘病毒药物（如靶向复制起始）提供了结构基础。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10937-2" target="_blank" rel="noreferrer">10.1038/s41586-026-10937-2</a></p><h3 id="🧬-把核糖体「改写」成只翻译自己-rna-上的蛋白——ribo-m-与-rna-世界难题" tabindex="-1">🧬 把核糖体「改写」成只翻译自己 RNA 上的蛋白——Ribo-M 与 RNA 世界难题 <a class="header-anchor" href="#🧬-把核糖体「改写」成只翻译自己-rna-上的蛋白——ribo-m-与-rna-世界难题" aria-label="Permalink to &quot;🧬 把核糖体「改写」成只翻译自己 RNA 上的蛋白——Ribo-M 与 RNA 世界难题&quot;">​</a></h3><p><strong>Rewiring the ribosome to translate proteins encoded in its own RNA</strong><em>Nature（2026-09-02）</em></p><p>细胞蛋白合成依赖核糖体与 mRNA 的<strong>随机碰撞</strong>，这让「为单一蛋白产量而优化翻译机器」变得困难——而这恰是生物制造的关键需求。一个可能的解法是<strong>把编码序列嵌进核糖体自身</strong>，让核糖体「专职」合成一条多肽；这同时触及 <strong>RNA 世界</strong>模型的一个长期难题：早期蛋白合成在组分稀缺、无序的情况下如何可靠运转？Kasra Alizadeh、Dorota Klepacki、Nora Vázquez-Laslop、Alexander S. Mankin（4 位作者）证明<strong>细菌核糖体确实能翻译编码在其自身 RNA 中的蛋白</strong>：他们把一段蛋白编码序列接到 <strong>16S rRNA</strong> 上，构建<strong>嵌合的信使—核糖体 RNA（mrRNA）</strong>；该杂合 mrRNA 组装成小亚基、与大亚基结合形成 <strong>Ribo-M</strong>，可翻译 mrRNA 编码的蛋白。<strong>凡破坏小亚基功能的突变或抗生素都能废止翻译</strong>，反证翻译确由这一杂合核糖体执行。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10962-1" target="_blank" rel="noreferrer">10.1038/s41586-026-10962-1</a></p><h3 id="🌫️-1999–2006-年大气甲烷「平台期」之谜-nox-排放上升与南移推高-oh" tabindex="-1">🌫️ 1999–2006 年大气甲烷「平台期」之谜：NOx 排放上升与南移推高 OH <a class="header-anchor" href="#🌫️-1999–2006-年大气甲烷「平台期」之谜-nox-排放上升与南移推高-oh" aria-label="Permalink to &quot;🌫️ 1999–2006 年大气甲烷「平台期」之谜：NOx 排放上升与南移推高 OH&quot;">​</a></h3><p><strong>Atmospheric CH4 plateau sustained by NOx emission rise and southward shift</strong><em>Nature（2026-09-02）</em></p><p>大气甲烷增速存在<strong>十年尺度波动</strong>：1990 年代增速放缓，2000 年代经济扩张本应推高人为排放，但<strong>全球监测网在 1999–2006 年几乎没测到甲烷增长</strong>——即所谓「甲烷平台期」，成因长期不确定。Yu Zhu、Lu Shen、Gang Liu、Kelvin H. Bates、Yuxin Cai、Shushi Peng（6 位作者）<strong>结合模式模拟与甲烷/同位素观测</strong>，把平台期归因于 2000–2006 年相对 1999 年<strong>羟基自由基（OH）上升 1.4 ± 0.4%</strong>，且主要发生在<strong>热带</strong>。而热带 OH 增强<strong>主要源于氮氧化物（NOx）排放的全球上升与空间再分布</strong>——向发展中地区与海洋转移，其推手是新兴经济体的增长。这意味着甲烷的「消失」不由其自身排放决定，而由<strong>决定其寿命的氧化剂 OH</strong> 的分布决定。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10983-w" target="_blank" rel="noreferrer">10.1038/s41586-026-10983-w</a></p><h3 id="🐸-青蛙用「脑源性酮体」让神经活动脱离葡萄糖运转" tabindex="-1">🐸 青蛙用「脑源性酮体」让神经活动脱离葡萄糖运转 <a class="header-anchor" href="#🐸-青蛙用「脑源性酮体」让神经活动脱离葡萄糖运转" aria-label="Permalink to &quot;🐸 青蛙用「脑源性酮体」让神经活动脱离葡萄糖运转&quot;">​</a></h3><p><strong>Transforming neural activity to operate without glucose metabolism using brain-derived ketone bodies</strong><em>PNAS（2026-09-02）</em></p><p>脊椎动物大脑对<strong>葡萄糖供应中断极其敏感</strong>，供糖失败即导致神经功能障碍——这几乎是一条铁律。Hafsa Yaseen、Karissa Cisneros、Rebecca Wright、Nikolaus Bueschke、Joseph M. Santin（5 位作者）却发现一个<strong>例外</strong>：青蛙的神经回路可以<strong>停止代谢葡萄糖</strong>，部分改用<strong>完全在脑内合成的酮体</strong>——这一转变发生在<strong>冬眠结束</strong>之后。机制上，酮体由<strong>星形胶质细胞合成并转运给神经元</strong>，为突触传递供能，同时伴随<strong>脂肪酸分解与酮体转运相关基因表达上调</strong>。脑源性酮体还能<strong>阻止缺氧时的活动衰减</strong>。这为理解青蛙如何在水下冬眠数月、并面对严重缺氧后<strong>重启脑回路</strong>提供了机制线索。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2613981123" target="_blank" rel="noreferrer">10.1073/pnas.2613981123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🎯-让语言模型自己「声明」该看哪里-declarative-attention" tabindex="-1">🎯 让语言模型自己「声明」该看哪里：Declarative Attention <a class="header-anchor" href="#🎯-让语言模型自己「声明」该看哪里-declarative-attention" aria-label="Permalink to &quot;🎯 让语言模型自己「声明」该看哪里：Declarative Attention&quot;">​</a></h3><p><strong>Language Models Can Control Their Own Attention</strong><em>arXiv（2026-09-02）</em></p><p>语言模型的注意力绝大多数落在一小部分上下文上，却仍要<strong>读完整条 KV 缓存</strong>才能找出那几个关键 token：在 100 万 token 的对话里问一个早先的细节，全局注意力层每生成一个 token 都得扫描全部上下文。主流做法是用轻量<strong>代理分数预先挑 token</strong>，但这种<strong>外源打分</strong>仍是每步 O(N)。Namgyu Ho 等（6 位作者）提出 <strong>Declarative Attention（DA）</strong>——一个<strong>内源</strong>方案，动机是「模型难道不知道自己该看哪儿吗？」：让模型在<strong>思维链里声明</strong>它需要关注的区域，并把生成划分为三种模式——<code>&lt;global&gt;</code>（全上下文）、<code>&lt;focus&gt;</code>（某个具体区域）、<code>&lt;local&gt;</code>（仅最近输出）。推理引擎像解析<strong>工具调用</strong>一样解析这些声明，从而跳过大部分 KV 缓存读取。在 <strong>15 个长上下文任务</strong>的零样本评测中，DA 让现成模型（Gemma-4-31B、Qwen-3.6-27B）显著降低了每次回答的总注意力 token 数。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.02737" target="_blank" rel="noreferrer">2609.02737</a></p><h3 id="🧪-先验证再蒸馏-on-policy-蒸馏的「提示级教师门控」-tgopd" tabindex="-1">🧪 先验证再蒸馏：on-policy 蒸馏的「提示级教师门控」（TGOPD） <a class="header-anchor" href="#🧪-先验证再蒸馏-on-policy-蒸馏的「提示级教师门控」-tgopd" aria-label="Permalink to &quot;🧪 先验证再蒸馏：on-policy 蒸馏的「提示级教师门控」（TGOPD）&quot;">​</a></h3><p><strong>Verify Before You Distill: Prompt-Level Teacher Gating for On-Policy Distillation</strong><em>arXiv（2026-09-02）</em></p><p><strong>在线策略蒸馏（OPD）<strong>用冻结教师对学生自身 rollout 给出</strong>token 级稠密监督</strong>，从而加速后训练；但原版 OPD 对<strong>所有提示一律施加</strong>这种监督，并不检查教师在该提示上是否可靠。而<strong>反向 KL 是寻模（mode-seeking）的</strong>，一个<strong>自信却错误</strong>的教师会造成强烈而<strong>误导性</strong>的更新。熵或师生似然一致度这类<strong>分布型代理</strong>只测不确定/一致，<strong>并不直接验证结果正确性</strong>。Zhiwei Zhang 等（9 位作者）提出 <strong>Teacher-Gated OPD（TGOPD）</strong>，原则是「稠密监督进入前，先<strong>在提示级验证教师可靠性</strong>」：用<strong>一小批经验证器打分的教师探针</strong>估计可靠性，通过的提示才走稠密 OPD，否则改走<strong>以验证器为依据的 GRPO</strong>。在 <strong>4B 与 35B</strong> 学生、数学/代码/指令遵循上，TGOPD 在<strong>全部六个单域设定</strong>中都优于原版 OPD。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.02998" target="_blank" rel="noreferrer">2609.02998</a></p><h3 id="🧾-errand-把「复核」当作要计价的差事——智能体记忆的预算化维护" tabindex="-1">🧾 ERRAND：把「复核」当作要计价的差事——智能体记忆的预算化维护 <a class="header-anchor" href="#🧾-errand-把「复核」当作要计价的差事——智能体记忆的预算化维护" aria-label="Permalink to &quot;🧾 ERRAND：把「复核」当作要计价的差事——智能体记忆的预算化维护&quot;">​</a></h3><p><strong>ERRAND: Budgeted Maintenance of Agent Memory</strong><em>arXiv（2026-09-02）</em></p><p>已部署的智能体靠<strong>交接来的知识</strong>运行：一个冻结的策略查阅在数据流开始前写好的「简报」。但<strong>世界在动、存储却静止</strong>——路径关闭、标志位改变、价格区间移动；每条条目在交接时都为真，出错源于<strong>陈旧（staleness）而非无知</strong>。Beining Wu、Zihao Ding、Jun Huang（3 位作者）提出 <strong>ERRAND</strong>：把<strong>再验证</strong>当成一件<strong>要计价的差事</strong>——一次复核与它所保护的任务争夺<strong>同样稀缺的动作</strong>，只有当「消除一个疑点的每动作价值」越过<strong>运行工资线</strong>时才拨款。该「差事指数」是<strong>单峰</strong>的、在信念两端都归零（<strong>无论笃定还是一无所知都无需花钱</strong>）；顺路免费的「回执」维持路径上的知识，修补<strong>写新版本、从不删除</strong>。在两个漂移的工具使用世界中、相同动作预算下，ERRAND <strong>全面胜过所有非 oracle 策略</strong>（在基准上限下比「急于复核」高 <strong>10.0pp</strong>）；不设上限时它<strong>自行停下</strong>，只花 <strong>11.0%</strong> 的步数。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.29545" target="_blank" rel="noreferrer">2609.29545</a></p><h3 id="📚-repo-to-skill-把-github-仓库蒸馏成可复用的「ai4ai-技能」" tabindex="-1">📚 Repo-To-Skill：把 GitHub 仓库蒸馏成可复用的「AI4AI 技能」 <a class="header-anchor" href="#📚-repo-to-skill-把-github-仓库蒸馏成可复用的「ai4ai-技能」" aria-label="Permalink to &quot;📚 Repo-To-Skill：把 GitHub 仓库蒸馏成可复用的「AI4AI 技能」&quot;">​</a></h3><p><strong>Repo-To-Skill: Distilling GitHub Repositories Into AI4AI Skills</strong><em>arXiv（2026-09-02）</em></p><p>自主智能体已开始端到端做机器学习研究，它们由模型骨干 + 负责规划/执行/记忆/验证的<strong>外骨架</strong>组成，但这套架构把领域<strong>诀窍留在了智能体之外</strong>。作者称之为<strong>操作知识（operational knowledge）</strong>——区分「知道一个方法」与「让方法真正跑通」的那层知识。它并非不存在，而是<strong>散落在仓库与论文里</strong>，以<strong>写给人类读者、且大到无法在任务中加载</strong>的形式存在；一旦蒸馏为<strong>紧凑、经过验证的技能</strong>，就能跨任务复用，而非每次运行重新发现。Jianlyu Chen 等（11 位作者）提出 <strong>DisCo</strong>——一个由技能驱动的研究智能体：蒸馏分两种互补形式，<strong>任务无关</strong>的（把领域常用仓库压缩成可复用技能）与<strong>任务导向</strong>的（产出具体任务所需技能）；前者施于开放生态，产出 <strong>AREX-Skill 库</strong>，含<strong>从仓库蒸馏的 5,000+ 条已验证技能</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.02749" target="_blank" rel="noreferrer">2609.02749</a></p><h3 id="🎲-语言模型的「荷兰赌」-用线性规划测概率预测的自洽性" tabindex="-1">🎲 语言模型的「荷兰赌」：用线性规划测概率预测的自洽性 <a class="header-anchor" href="#🎲-语言模型的「荷兰赌」-用线性规划测概率预测的自洽性" aria-label="Permalink to &quot;🎲 语言模型的「荷兰赌」：用线性规划测概率预测的自洽性&quot;">​</a></h3><p><strong>Dutch Books for Language Models</strong><em>arXiv（2026-09-02）</em></p><p>人们越来越多地用语言模型辅助人生决策，其中许多涉及<strong>概率预测</strong>（重大人生事件、自然灾害、经济结果的可能性）。用户往往会<strong>默认</strong>这些预测出自一个<strong>自洽的世界模型</strong>。Isaiah Andrews 与 Suproteem Sarkar（2 位作者）基于 <strong>de Finetti 的一个定理</strong>评估语言模型概率预测的<strong>自洽性</strong>：他们从<strong>股票收益数据</strong>生成事件、向语言模型抽取预测，再用<strong>线性规划</strong>计算<strong>最大的「荷兰赌」利润</strong>——即套利者靠押注「模型给出的概率」可<strong>保证</strong>获得的收益，以此度量<strong>不自洽程度</strong>。该程序<strong>不需要结果标签</strong>，因此即便事件的结局尚未发生、未被观测，也能评估自洽性。他们发现语言模型预测存在<strong>显著的不自洽</strong>：当事件之间存在<strong>更丰富的逻辑关系</strong>时更严重，而<strong>无关的上下文细节</strong>也会加剧它。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.02797" target="_blank" rel="noreferrer">2609.02797</a></p><blockquote><p>📅 日期：2026-09-02 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 ｜ （第 ? 期 · 事后重建版）</p></blockquote>',45)])])}const u=t(e,[["render",a]]);export{d as __pageData,u as default};
